import{_ as t,c as o,o as a,ag as i}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common issues and solutions","frontmatter":{"title":"Troubleshooting","description":"Common issues and solutions"},"headers":[],"relativePath":"engine/troubleshooting.md","filePath":"engine/troubleshooting.md","lastUpdated":1788476353000}'),s={name:"engine/troubleshooting.md"};function r(n,e,l,c,d,h){return a(),o("div",null,e[0]||(e[0]=[i(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common issues and solutions when running OIE.</p><h2 id="server-won-t-start" tabindex="-1">Server won&#39;t start <a class="header-anchor" href="#server-won-t-start" aria-label="Permalink to &quot;Server won&#39;t start&quot;">​</a></h2><h3 id="java-not-found" tabindex="-1">Java not found <a class="header-anchor" href="#java-not-found" aria-label="Permalink to &quot;Java not found&quot;">​</a></h3><p><strong>Symptom:</strong> Error about missing Java or unsupported version.</p><p><strong>Solution:</strong></p><ol><li>Ensure Java 17+ is installed: <code>java -version</code></li><li>Set <code>OIE_JAVA_PATH</code> environment variable to the correct Java path</li><li>Or configure <code>-java-cmd</code> in <code>conf/custom.vmoptions</code></li><li>Use SDKMAN to install the correct version: <code>sdk env install</code></li></ol><h3 id="port-already-in-use" tabindex="-1">Port already in use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to &quot;Port already in use&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Address already in use</code> error on startup.</p><p><strong>Solution:</strong></p><ol><li>Check which process is using the port: <ul><li>Linux/macOS: <code>lsof -i :8443</code></li><li>Windows: <code>netstat -ano | findstr 8443</code></li></ul></li><li>Stop the conflicting process</li><li>Or change OIE ports in <code>conf/mirth.properties</code>:<div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8080</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8443</span></span></code></pre></div></li></ol><h3 id="database-connection-failed" tabindex="-1">Database connection failed <a class="header-anchor" href="#database-connection-failed" aria-label="Permalink to &quot;Database connection failed&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Unable to connect to database</code> error.</p><p><strong>Solution:</strong></p><ol><li>Verify the database server is running</li><li>Check <code>database.url</code>, <code>database.username</code>, and <code>database.password</code> in <code>mirth.properties</code></li><li>Ensure the database exists and the user has permissions</li><li>Check firewall rules between OIE and the database</li><li>Review <code>database.connection.maxretry</code> and retry settings</li></ol><h3 id="out-of-memory" tabindex="-1">Out of memory <a class="header-anchor" href="#out-of-memory" aria-label="Permalink to &quot;Out of memory&quot;">​</a></h3><p><strong>Symptom:</strong> <code>OutOfMemoryError</code> in logs.</p><p><strong>Solution:</strong></p><ol><li>Increase heap size in <code>conf/custom.vmoptions</code>:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xmx1024m</span></span></code></pre></div></li><li>Reduce <code>database.max-connections</code> if too many connections are open</li><li>Check for channels with unbounded map growth</li></ol><h2 id="administrator-can-t-connect" tabindex="-1">Administrator can&#39;t connect <a class="header-anchor" href="#administrator-can-t-connect" aria-label="Permalink to &quot;Administrator can&#39;t connect&quot;">​</a></h2><h3 id="connection-refused" tabindex="-1">Connection refused <a class="header-anchor" href="#connection-refused" aria-label="Permalink to &quot;Connection refused&quot;">​</a></h3><p><strong>Symptom:</strong> Administrator shows &quot;Connection refused&quot; or timeout.</p><p><strong>Solution:</strong></p><ol><li>Verify the server is running</li><li>Check that port 8443 is accessible (firewall rules)</li><li>Verify the server URL is correct (<code>https://host:8443</code>)</li><li>Check if <code>https.host</code> is set to <code>127.0.0.1</code> (only allows local connections)</li></ol><h3 id="certificate-errors" tabindex="-1">Certificate errors <a class="header-anchor" href="#certificate-errors" aria-label="Permalink to &quot;Certificate errors&quot;">​</a></h3><p><strong>Symptom:</strong> SSL/TLS certificate warnings or errors.</p><p><strong>Solution:</strong></p><ol><li>Self-signed certificates trigger browser warnings - click through to continue</li><li>For production, install a CA-signed certificate into the keystore (or use the <a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager plugin</a> if installed)</li><li>Ensure <code>https.client.protocols</code> includes protocols supported by the client</li></ol><h3 id="login-fails" tabindex="-1">Login fails <a class="header-anchor" href="#login-fails" aria-label="Permalink to &quot;Login fails&quot;">​</a></h3><p><strong>Symptom:</strong> &quot;Invalid username or password&quot; error.</p><p><strong>Solution:</strong></p><ol><li>Verify the username and password are correct</li><li>Check if the account is locked (exceeded <code>password.retrylimit</code>)</li><li>Reset the password via the CLI: <code>user changepw admin &quot;newpassword&quot;</code></li><li>Check if the password has expired</li></ol><h2 id="channel-issues" tabindex="-1">Channel issues <a class="header-anchor" href="#channel-issues" aria-label="Permalink to &quot;Channel issues&quot;">​</a></h2><h3 id="channel-won-t-start" tabindex="-1">Channel won&#39;t start <a class="header-anchor" href="#channel-won-t-start" aria-label="Permalink to &quot;Channel won&#39;t start&quot;">​</a></h3><p><strong>Symptom:</strong> Channel stays in STOPPED state after clicking Start.</p><p><strong>Solution:</strong></p><ol><li>Check the <strong>Server Log</strong> panel on the Dashboard tab in the Administrator for errors</li><li>Verify the source connector port is not already in use</li><li>Check channel dependencies - required channels must be started first</li><li>Look for script errors in deploy scripts</li><li>Verify external resources (databases, file paths) are accessible</li></ol><h3 id="messages-not-being-received" tabindex="-1">Messages not being received <a class="header-anchor" href="#messages-not-being-received" aria-label="Permalink to &quot;Messages not being received&quot;">​</a></h3><p><strong>Symptom:</strong> Channel is started but no messages appear.</p><p><strong>Solution:</strong></p><ol><li>Verify the sending system is pointing to the correct host and port</li><li>Check firewall rules</li><li>For TCP/MLLP: ensure the transmission mode matches (MLLP framing)</li><li>For File Reader: verify the directory path and file name filter</li><li>For Database Reader: test the SQL query manually</li><li>Check the Connector Status panel on the Dashboard tab in the Administrator for connection events</li></ol><h3 id="messages-stuck-in-queue" tabindex="-1">Messages stuck in queue <a class="header-anchor" href="#messages-stuck-in-queue" aria-label="Permalink to &quot;Messages stuck in queue&quot;">​</a></h3><p><strong>Symptom:</strong> Queue count increases, messages not being sent.</p><p><strong>Solution:</strong></p><ol><li>Check destination connector errors in the Message Browser</li><li>Verify the destination system is reachable</li><li>Check for connection timeouts or authentication failures</li><li>Review queue settings (retry interval, max retries)</li><li>Stop and restart the channel to reset queue threads</li></ol><h3 id="transformer-errors" tabindex="-1">Transformer errors <a class="header-anchor" href="#transformer-errors" aria-label="Permalink to &quot;Transformer errors&quot;">​</a></h3><p><strong>Symptom:</strong> Messages show ERROR status with transformer exceptions.</p><p><strong>Solution:</strong></p><ol><li>Open the message in the Message Browser and check the <strong>Errors</strong> tab</li><li>Common issues: <ul><li><code>TypeError</code> - Accessing a field that doesn&#39;t exist; check the message structure</li><li><code>ReferenceError</code> - Using an undefined variable</li><li><code>NullPointerException</code> - Accessing properties on null/undefined</li></ul></li><li>Load a sample message in the transformer editor to verify field paths</li><li>Use <code>logger.debug()</code> to trace variable values</li><li>Wrap risky operations in try/catch blocks</li></ol><h3 id="filter-not-working" tabindex="-1">Filter not working <a class="header-anchor" href="#filter-not-working" aria-label="Permalink to &quot;Filter not working&quot;">​</a></h3><p><strong>Symptom:</strong> Messages are being accepted/rejected unexpectedly.</p><p><strong>Solution:</strong></p><ol><li>Check filter rule order and boolean operators (AND vs OR)</li><li>Verify field paths match the actual message structure</li><li>For JavaScript filters, add logging to verify conditions:<div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Message type: &#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.9&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.9.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div></li><li>Remember: <code>return true</code> = accept, <code>return false</code> = reject</li></ol><h2 id="performance-issues" tabindex="-1">Performance issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance issues&quot;">​</a></h2><h3 id="high-cpu-usage" tabindex="-1">High CPU usage <a class="header-anchor" href="#high-cpu-usage" aria-label="Permalink to &quot;High CPU usage&quot;">​</a></h3><p><strong>Solution:</strong></p><ol><li>Check for channels with high message volume and complex transformers</li><li>Reduce polling frequency on File Reader and Database Reader sources</li><li>Review JavaScript code for inefficient loops or operations</li><li>Increase channel thread counts for parallel processing</li><li>Check for infinite loops in scripts</li></ol><h3 id="high-memory-usage" tabindex="-1">High memory usage <a class="header-anchor" href="#high-memory-usage" aria-label="Permalink to &quot;High memory usage&quot;">​</a></h3><p><strong>Solution:</strong></p><ol><li>Increase heap size in <code>conf/custom.vmoptions</code></li><li>Reduce message storage mode (Development uses the most memory)</li><li>Enable content pruning</li><li>Check for large messages consuming memory</li><li>Review global map usage - avoid storing large objects</li></ol><h3 id="slow-database-performance" tabindex="-1">Slow database performance <a class="header-anchor" href="#slow-database-performance" aria-label="Permalink to &quot;Slow database performance&quot;">​</a></h3><p><strong>Solution:</strong></p><ol><li>Enable <code>database.enable-read-write-split</code></li><li>Run database maintenance (VACUUM for PostgreSQL, OPTIMIZE for MySQL)</li><li>Ensure database indexes are up to date</li><li>Increase <code>database.max-connections</code> if connections are saturated</li><li>Configure message pruning to keep the database lean</li></ol><h2 id="common-error-messages" tabindex="-1">Common error messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common error messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td><code>Address already in use</code></td><td>Port conflict</td><td>Change port or stop conflicting process</td></tr><tr><td><code>Unable to connect to database</code></td><td>Database unreachable</td><td>Check DB settings and connectivity</td></tr><tr><td><code>OutOfMemoryError</code></td><td>Insufficient heap</td><td>Increase <code>-Xmx</code> in vmoptions</td></tr><tr><td><code>SSLHandshakeException</code></td><td>TLS mismatch</td><td>Check protocol/cipher settings</td></tr><tr><td><code>ConnectException: Connection refused</code></td><td>Destination unreachable</td><td>Verify host/port and network</td></tr><tr><td><code>SocketTimeoutException</code></td><td>Network timeout</td><td>Increase timeout settings</td></tr><tr><td><code>ScriptCompileException</code></td><td>JavaScript syntax error</td><td>Fix the script syntax</td></tr><tr><td><code>TransformerException</code></td><td>Runtime transformer error</td><td>Check error details in Message Browser</td></tr></tbody></table><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><ul><li><strong>Logs:</strong> Check <code>logs/mirth.log</code> for detailed error information</li><li><strong>Event Browser:</strong> Review system events for operational issues</li><li><strong>Discord:</strong> <a href="https://discord.gg/azdehW2Zrx" target="_blank" rel="noreferrer">Join the community</a></li><li><strong>GitHub Issues:</strong> <a href="https://github.com/OpenIntegrationEngine/engine/issues" target="_blank" rel="noreferrer">Report a bug</a></li><li><strong>Security Issues:</strong> <a href="mailto:security@openintegrationengine.org" target="_blank" rel="noreferrer">security@openintegrationengine.org</a></li></ul>`,67)]))}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
